TOOL_HTML='<div class="card finder reveal" id="finder"><h3 data-i18n="fd_h"></h3><p class="small" data-i18n="fd_p"></p>\n   <div class="ff">\n    <div><label for="fL" data-i18n="fd_len"></label><input id="fL" type="number" min="10" value="330"></div>\n    <div><label for="fW" data-i18n="fd_wid"></label><input id="fW" type="number" min="10" value="250"></div>\n    <div><label for="fT" data-i18n="fd_thk"></label><input id="fT" type="number" min="0.1" step="0.1" value="1.6"></div>\n    <div><label for="fS" data-i18n="fd_src"></label><select id="fS"><option value="1" data-i18n="fd_s1"></option><option value="2" data-i18n="fd_s2"></option><option value="3" data-i18n="fd_s3"></option><option value="4" data-i18n="fd_s4"></option><option value="5" data-i18n="fd_s5"></option></select></div>\n    <div class="chk"><label><input id="fTight" type="checkbox"> <span data-i18n="fd_tight"></span></label></div>\n   </div>\n   <div class="fres"><span class="small" data-i18n="fd_res"></span><b id="fModel">—</b><span id="fWhy"></span><span class="small" id="fAlt"></span><button type="button" class="btn btn-p" id="fGo"><i class="fa-solid fa-cube"></i><span data-i18n="fd_go"></span></button></div>\n  </div>'
TOOL_JS='/* loader finder */\nvar FM=[["SLD250",330,250],["SLD330",445,330],["SLD390",530,390],["SLD460",530,460]],FL=[["SLF250",330,250],["SLF330",445,330],["SLF390",530,390]],\n FB=[["SBU330",330,330],["SBU460",460,460]],FV=[["SVL250",445,330],["SVL390",500,390],["SVL330",530,460],["SVL460",535,460]],\n FD=[["SLD250-D",350,250],["SLD250-V",350,250],["SLD330-V",445,330],["SLD390-D",460,390],["SLD390-V",535,390]];\nfunction fit(list,L,W){for(var i=0;i<list.length;i++){if(L<=list[i][1]&&W<=list[i][2])return list[i][0];}return null;}\nvar fMode=0;\nfunction finder(){var L=Math.max(num("fL"),num("fW")),W=Math.min(num("fL"),num("fW")),th=num("fT"),s=document.getElementById("fS").value,tight=document.getElementById("fTight").checked;\n var m=null,why="",alt="",md=0;\n if(s==="4"){m="SFBL250";why="fr9";md=8;}\n else if(s==="5"){if(L<=350&&W<=150&&L>=80&&W>=50){m="SL600A";why="fr8";md=7;}}\n else if(L>535){if(s==="2"){if(L<=1300&&W<=330){m="SVL330 (1.5 m)";why="fr10";md=4;}}else if(L<=1200&&W<=350){m="SLD350L";why="fr7";md=6;}}\n else if(s==="1"){if(tight&&L<=445&&W<=350){m="S-MLD250";why="fr2";md=1;var a=fit(FL,L,W);if(a)alt=a;}\n  else if(tight){m=fit(FL,L,W);why="fr3";md=2;}\n  else{m=fit(FM,L,W);why="fr1";md=0;var a2=fit(FL,L,W);if(a2)alt=a2;}}\n else if(s==="2"){m=fit(FB,L,W);why="fr4";md=3;var a3=fit(FV,L,W);if(a3)alt=a3;if(!m){m=a3;why="fr5";md=4;alt="";}}\n else if(s==="3"){m=fit(FD,L,W);why="fr6";md=5;}\n if(s==="5"&&(th>2.0||th<0.2))m=null;\n fMode=md;document.getElementById("fModel").textContent=m||"—";document.getElementById("fWhy").textContent=m?T(why):T("fd_none");\n document.getElementById("fAlt").textContent=(m&&alt&&alt!==m)?T("fd_alt")+": "+alt:"";document.getElementById("fGo").style.display=m?"":"none";}\n["fL","fW","fT","fS","fTight"].forEach(function(id){var e=document.getElementById(id);e.addEventListener("input",finder);e.addEventListener("change",finder);});\ndocument.getElementById("fGo").addEventListener("click",function(){showStation(fMode);document.getElementById("line3d").scrollIntoView({behavior:"smooth"});});\nwindow.__toolRefresh=finder;'
